def max_subarray(nums):
    max_sum = nums[0]
    curr_sum = nums[0]
    for i in range(1, len(nums)):
        if curr_sum < 0:
            curr_sum = nums[i]
        else:
            curr_sum = curr_sum + nums[i]
        if curr_sum > max_sum:
            max_sum = curr_sum
    return max_sum

